const fs=require('fs');
const read=p=>fs.readFileSync(p,'utf8');
const write=(p,s)=>fs.writeFileSync(p,s);

const salesMain=String.raw`<main id="main">
<section class="subsite-hero energy sales-hero"><div class="inner"><p class="subsite-label">Energy &amp; Global Trade / Industrial Sales</p><h1>Industrial<br>Sales.</h1><p class="intro">A structured commercial inquiry route for petrochemical, industrial-chemical and related product requirements. Define the requirement, prepare the RFQ, and send it directly to the Industrial Sales desk for review.</p><div class="sales-hero-actions"><a class="button-link primary" href="#rfq-builder">Prepare industrial RFQ</a><a class="button-link" href="mailto:sales@uniqueholding.com.tr">Email Industrial Sales</a></div><p class="sales-handoff-note">This page does not submit or store an RFQ on a server. It prepares a structured email for you to send through your email application.</p><a class="back" href="products.html">View products ↗</a></div></section>
<nav class="sales-process-strip" aria-label="Industrial RFQ commercial sequence"><ol><li><small>01</small><strong>Define the Requirement</strong><span>Product and buyer parameters</span></li><li><small>02</small><strong>Submit Commercial Details</strong><span>Email handoff to Industrial Sales</span></li><li><small>03</small><strong>Review &amp; Qualification</strong><span>Requirement and route review</span></li><li><small>04</small><strong>Offered-Lot Confirmation</strong><span>Transaction-specific confirmation</span></li><li><small>05</small><strong>Commercial Next Step</strong><span>Relevant next action after review</span></li></ol></nav>
<section class="subsite-section sales-builder-section"><div class="section-cap"><span class="num">01–02 / Define &amp; Prepare</span><h2>Build a buyer-ready requirement.</h2><p>Complete every field that is known. The builder keeps the information in your browser and prepares an email addressed to sales@uniqueholding.com.tr; your email application is the actual sending channel.</p></div><div class="rfq-layout"><form id="rfq-builder" class="rfq-builder" aria-describedby="rfq-local-note"><div class="rfq-context" id="rfq-context" hidden></div><div class="rfq-grid">
<label class="rfq-field" for="rfq-product"><span><b>01 / Product</b><small>Product name or accepted abbreviation</small></span><input id="rfq-product" name="product" type="text" maxlength="160" autocomplete="off"></label>
<label class="rfq-field" for="rfq-grade"><span><b>02 / Grade / Specification</b><small>Required grade, form, concentration or commercial variant where known</small></span><input id="rfq-grade" name="grade" type="text" maxlength="240" autocomplete="off"></label>
<label class="rfq-field" for="rfq-quantity"><span><b>03 / Quantity</b><small>Required quantity and delivery schedule where relevant</small></span><input id="rfq-quantity" name="quantity" type="text" maxlength="160" inputmode="text" autocomplete="off"></label>
<label class="rfq-field" for="rfq-destination"><span><b>04 / Destination</b><small>Country, port, city or delivery point for commercial review</small></span><input id="rfq-destination" name="destination" type="text" maxlength="240" autocomplete="shipping locality"></label>
<label class="rfq-field" for="rfq-timing"><span><b>05 / Timing</b><small>Required shipment or delivery window</small></span><input id="rfq-timing" name="timing" type="text" maxlength="180" autocomplete="off"></label>
<label class="rfq-field rfq-field-wide" for="rfq-specification"><span><b>06 / Specification / Technical Requirement</b><small>Target specification, buyer parameters or technical requirement. The website does not validate technical suitability.</small></span><textarea id="rfq-specification" name="specification" rows="7" maxlength="4000"></textarea></label>
</div><fieldset class="rfq-contact"><legend>07 / Contact</legend><p>Provide the contact details useful for commercial follow-up. No account is created.</p><div class="rfq-contact-grid"><label for="rfq-contact-name"><span>Contact name</span><input id="rfq-contact-name" name="contactName" type="text" maxlength="160" autocomplete="name"></label><label for="rfq-company"><span>Company</span><input id="rfq-company" name="company" type="text" maxlength="200" autocomplete="organization"></label><label for="rfq-email"><span>Email</span><input id="rfq-email" name="email" type="email" maxlength="254" autocomplete="email" inputmode="email"></label><label for="rfq-phone"><span>Phone</span><input id="rfq-phone" name="phone" type="tel" maxlength="80" autocomplete="tel" inputmode="tel"></label></div></fieldset><label class="rfq-field rfq-field-wide rfq-notes" for="rfq-notes"><span><b>Additional Notes</b><small>Optional transaction context that does not fit the requirement fields above</small></span><textarea id="rfq-notes" name="notes" rows="4" maxlength="2000"></textarea></label><div class="rfq-handoff" id="rfq-local-note" role="note"><strong>Email handoff — not server submission</strong><p>The form is processed locally in this browser. Selecting “Prepare email RFQ” opens your email application with a structured draft addressed to <a href="mailto:sales@uniqueholding.com.tr">sales@uniqueholding.com.tr</a>. Nothing on this page represents receipt, acceptance or quotation.</p></div><div class="rfq-actions"><a class="button-link primary" id="rfq-email-action" href="mailto:sales@uniqueholding.com.tr">Prepare email RFQ</a><button class="button-link rfq-reset" id="rfq-reset" type="reset">Clear fields</button><a class="button-link" href="products.html">View products</a></div></form><aside class="sales-direct" aria-label="Industrial Sales direct contact"><span class="subsite-label">Direct commercial contact</span><h2>Industrial Sales desk</h2><p>For a direct handoff, use the approved commercial email or public business telephone numbers.</p><a href="mailto:sales@uniqueholding.com.tr">sales@uniqueholding.com.tr</a><a href="tel:+902127272222">+90 212 727 22 22</a><a href="tel:+905393809197">+90 539 380 91 97</a><small>Operating company</small><strong>UNIQE OTOMOTİV KİMYA SANAYİ LİMİTED ŞİRKETİ</strong></aside></div></section>
<section class="subsite-section alt"><div class="section-cap"><span class="num">03 / Review &amp; Qualification</span><h2>Commercial review starts with the requirement.</h2><p>The inquiry is reviewed rather than automatically matched or quoted. Published reference information can support initial review, but it does not determine the final offered-lot specification.</p></div><div class="commercial-review-grid"><article><small>Requirement</small><h3>Buyer parameters</h3><p>Product, grade or target specification, quantity, destination, timing and technical requirement are reviewed for commercial context.</p></article><article><small>Qualification</small><h3>Commercial route review</h3><p>Relevant commercial options are reviewed against the requested requirement. The site does not represent this step as automatic sourcing or guaranteed availability.</p></article><article><small>Technical context</small><h3>Reference versus offered lot</h3><p>Published reference information supports initial review. Final offered-lot specification and commercial terms are confirmed during commercial review.</p></article></div></section>
<section class="subsite-section paper"><div class="section-cap"><span class="num">04 / Offered-Lot Confirmation</span><h2>Standing catalog facts stop where transaction-specific review begins.</h2><p>When appropriate to the transaction, producer, origin, packing, final specification, availability and commercial terms are confirmed against the offered lot. They are not represented here as standing catalog guarantees.</p></div><div class="sales-boundary" role="note"><strong>Commercial boundary</strong><p>An RFQ is a request for commercial review. Preparing or sending the email does not itself confirm stock, supply, producer, origin, specification, acceptance or commercial terms.</p></div></section>
<section class="subsite-section"><div class="section-cap"><span class="num">05 / Commercial Next Step</span><h2>Continue through the Industrial Sales desk.</h2><p>After review, the relevant next commercial step can be handled against the specific requirement and offered-lot context.</p></div><div class="sales-next"><div><span class="subsite-label">Commercial email</span><a class="sales-next-email" href="mailto:sales@uniqueholding.com.tr">sales@uniqueholding.com.tr</a><p>Corporate contact remains available at <a href="mailto:farahmand@uniqueholding.com.tr">farahmand@uniqueholding.com.tr</a>.</p></div><div class="detail-cta"><a class="button-link primary" href="#rfq-builder">Prepare industrial RFQ</a><a class="button-link" href="products.html">View products</a></div></div></section>
</main>`;

const salesScript=String.raw`<script>(function(){const form=document.getElementById('rfq-builder');const action=document.getElementById('rfq-email-action');const reset=document.getElementById('rfq-reset');const product=document.getElementById('rfq-product');const context=document.getElementById('rfq-context');const get=id=>document.getElementById(id).value.trim();const limit=(value,max)=>String(value||'').slice(0,max);const params=new URLSearchParams(location.search);const prefill=limit(params.get('product'),160);if(prefill){product.value=prefill;context.textContent='Product context: '+prefill;context.hidden=false;}function updateMailto(){const productValue=get('rfq-product');const subject='Industrial RFQ — '+(productValue||'Unique Holding');const body=['Product: '+productValue,'Grade / Specification: '+get('rfq-grade'),'Quantity: '+get('rfq-quantity'),'Destination: '+get('rfq-destination'),'Timing: '+get('rfq-timing'),'Technical Specification / Requirement: '+get('rfq-specification'),'','Contact Name: '+get('rfq-contact-name'),'Company: '+get('rfq-company'),'Email: '+get('rfq-email'),'Phone: '+get('rfq-phone'),'','Additional Notes: '+get('rfq-notes')].join('\n');action.href='mailto:sales@uniqueholding.com.tr?subject='+encodeURIComponent(subject)+'&body='+encodeURIComponent(body);}form.addEventListener('input',updateMailto);form.addEventListener('change',updateMailto);form.addEventListener('submit',event=>event.preventDefault());form.addEventListener('reset',()=>queueMicrotask(()=>{if(prefill){product.value=prefill;context.textContent='Product context: '+prefill;context.hidden=false;}else{context.textContent='';context.hidden=true;}updateMailto();}));reset.addEventListener('click',()=>{});updateMailto();})();</script>`;

let sales=read('sales.html');
sales=sales.replace('<link rel="stylesheet" href="assets/internal.css"></head>','<link rel="stylesheet" href="assets/internal.css"><link rel="stylesheet" href="assets/industrial-sales.css"></head>');
sales=sales.replace(/<main id="main">[\s\S]*?<\/main>/,salesMain);
sales=sales.replace(/<script>const subject='Industrial RFQ — Unique Holding';[\s\S]*?<\/script><script src="assets\/site\.js" defer><\/script>/,salesScript+'<script src="assets/site.js" defer></script>');
write('sales.html',sales);

